package io.nop.treesitter.compat;

import io.nop.treesitter.language.Language;
import io.nop.treesitter.scanner.BashScanner;

/**
 * Bash language adapter ({@code org.treesitter.TreeSitterBash} shape) over the
 * vendored pure-Java bash grammar blob (upstream tree-sitter-bash
 * {@code v0.25.1}, generated by tree-sitter v0.25.10). Bash needs all 29 of its
 * external tokens — heredoc start/body/end, file descriptors, regex flavors,
 * expansion words, extglob patterns and the {@code ${...}} operator symbols —
 * so the language wires its scanner factory here; consumers parse through the
 * plain compat API exactly like the JNI version.
 */
public class TreeSitterBash implements TreeSitterLanguage {

    private static final Language LANGUAGE =
            Language.fromClasspath("/grammars/bash/tree-sitter-bash-blob.bin");

    static {
        LANGUAGE.setExternalScannerFactory(BashScanner::new);
    }

    @Override
    public Language language() {
        return LANGUAGE;
    }
}
